const paths={book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z M20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h3z',pen:'m15 4 5 5M4 16 17 3l4 4L8 20l-5 1z',film:'M4 3h16v18H4zM8 3v18M16 3v18M4 8h4M4 16h4M16 8h4M16 16h4',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4z',bot:'M5 8h14v12H5zM9 12v3M15 12v3M12 8V3M10 3h4M2 12v5M22 12v5',flow:'M6 4v12a4 4 0 0 0 4 4h5M6 8h9a4 4 0 0 0 4-4M3 2h6v5H3zM16 17h6v5h-6z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM21 2v4M19 4h4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 6 5 12 0 18M12 3c-5 6-5 12 0 18',flask:'M9 3h6M10 3v7L4 20h16l-6-10V3M7 15h10',library:'M3 4h4v16H3zM10 4h4v16h-4zM17 4l4-1 4 16-4 1z',bulb:'M9 18h6M10 21h4M8 14a7 7 0 1 1 8 0l-1 3H9z',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',chart:'M4 3v18h18M9 17v-5M14 17V7M19 17v-9',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M10 2h4l1 4 4 1 3 4-3 3v5l-5 1-2 2-4-3H4v-5L2 11l3-4 4-1z',search:'M17 17l5 5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 4v16M4 12h16',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',arrow:'m9 5 7 7-7 7',check:'m4 12 5 5L20 6',clock:'M12 6v6l4 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',folder:'M3 5h7l2 3h9v12H3z',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',copy:'M9 3h12v14H9zM5 7H3v14h12v-2',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',back:'M20 12H4m6-6-6 6 6 6',save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8z'};
const icon=(name='file')=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]??paths.file}"/></svg>`;
const btn=(text,action,cls='',id='',ico='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${text}</button>`;
const ib=(action,id,ico,label)=>`<button class="icon-btn" title="${label}" aria-label="${label}" data-action="${action}" data-id="${esc(id)}">${icon(ico)}</button>`;
const state={objects:[],jobs:[],page:'works',filter:'all',search:'',work:null,chapter:null,chapters:[],stats:{},dirty:false,job:null,tool:null,toastTimer:null,saving:null,editorTimer:null,initialized:false};
const navs=[['创作空间',[['works','我的作品','book'],['short','短篇小说','pen'],['script','我的剧本','film']]],['AI 创作',[['templates','模板中心','file'],['tools','创作工具','spark'],['agents','智能体','bot'],['workflows','工作流','flow']]],['素材与灵感',[['analysis','文本拆解','library'],['sources','资料采集','globe'],['titles','书名测试','flask'],['knowledge','知识库','library'],['ideas','灵感库','bulb']]],['创作管理',[['history','生成记录','clock'],['ratings','模型评测','chart']]]];
const pageMeta={works:['我的作品','每一个故事，都从这里开始。'],short:['短篇小说','把一个闪念，写成一个完整的故事。'],script:['我的剧本','从故事梗概到分场对白，让灵感走进镜头。'],templates:['模板中心','好用的提示词，让创作更进一步。'],tools:['创作工具','章节、人物、世界观与故事结构，全流程辅助。'],agents:['智能体','为你的创作，配备一位专属 AI 助手。'],workflows:['工作流','串联创作步骤，把想法逐步打磨成文。'],analysis:['文本拆解','理解结构与叙事技巧，沉淀自己的创作方法。'],sources:['资料采集','记录来源与阅读笔记，建立可追溯的素材库。'],titles:['书名测试','先用可解释的规则，检查书名的表达。'],knowledge:['知识库','收集创作资料，让每一次积累都能用上。'],ideas:['灵感库','捕捉转瞬即逝的想法，留给下一个故事。'],history:['生成记录','任务进度、分步输出与候选稿，都保存在这里。'],ratings:['模型评测','记录自己的真实使用体验，对比不同模型。'],settings:['模型与数据','兼容 OpenAI 格式接口，密钥仅保存在本地服务端。'],trash:['回收站','误删的作品和素材可以从这里恢复。'],skills:['写作技能','把自己的写作经验，变成智能体的检查清单。']};
const typeLabels={novel:'长篇小说',short:'短篇小说',script:'剧本'};
function objs(kind){return state.objects.filter(o=>o.kind===kind)}
function object(id){return state.objects.find(o=>o.id===id)}
function count(s){return String(s??'').replace(/\s/g,'').length}
function num(n){return n>=10000?(n/10000).toFixed(1)+'万':String(n)}
function date(s){return new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),4500)}
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify(data??{})});const j=await r.json();if(!r.ok)throw Object.assign(new Error(j.error??'请求失败'),{status:r.status});return j}
async function refresh(){const data=await api('state');Object.assign(state,data);const rows=await Promise.all(objs('work').map(async w=>[w.id,await api('chapters?work='+w.id)]));state.stats=Object.fromEntries(rows.map(([id,c])=>[id,{chapters:c.length,words:c.reduce((n,v)=>n+v.words,0)}]));}
function layout(){const today=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('#app').innerHTML=`<header class="topbar"><div class="actions"><button class="mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><button class="brand" data-action="nav" data-id="works"><span class="brandmark">${icon('pen')}</span><span><strong>墨舟 <span class="muted">AI</span></strong><small>INKFLOW · WRITING STUDIO</small></span></button></div><div class="top-center"><span class="status-dot"></span>独属于你的创作空间 <span>·</span> 本地保存，安心落笔</div><div class="top-actions"><button data-action="theme" title="切换外观">${icon('sun')} <span class="label">外观</span></button><button data-action="nav" data-id="history">${icon('clock')} <span class="label">历史</span></button><button data-action="nav" data-id="settings">${icon('settings')} <span class="label">模型设置</span></button><span class="avatar">墨</span></div></header><aside class="sidebar"><div class="greeting"><p>${esc(today)}</p><strong>留一点时间，<br>写自己的故事。</strong>${icon('spark')}</div><nav class="nav">${navs.map(([label,items])=>`<div class="nav-label">${label}</div>${items.map(([id,title,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-action="nav" data-id="${id}">${icon(ico)}${title}</button>`).join('')}`).join('')}</nav><div class="side-footer"><div><span class="status-dot"></span>本地工作空间 · v0.1</div><div class="actions" style="margin-top:10px"><button data-action="nav" data-id="trash">${icon('trash')} 回收站</button><button data-action="help">使用指南 ${icon('arrow')}</button></div></div></aside><main class="main" id="content"></main>`;renderPage();}
function head(actions=''){const [title,sub]=pageMeta[state.page]??['创作工作台',''];return `<div class="page-head"><div><div class="eyebrow">INKFLOW / YOUR CREATIVE SPACE</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function footer(){return '<div class="footer">墨舟 AI · 让灵感落笔，让故事远行</div>'}
function empty(title,sub,action='',label='立即创建'){return `<div class="empty">${icon('pen')}<h3>${title}</h3><p>${sub}</p>${action?btn(label,action,'primary','','plus'):''}</div>`}
function search(){return `<label class="search">${icon('search')}<input id="search" placeholder="搜索标题、内容、标签…" value="${esc(state.search)}" aria-label="搜索"></label>`}
function matches(o){const q=state.search.trim().toLowerCase();return !q||(o.title+' '+JSON.stringify(o.data)).toLowerCase().includes(q)}
function renderPage(){const content=$('#content');if(!content)return;if(state.page==='editor'){renderEditor();return}if(['works','short','script'].includes(state.page))content.innerHTML=worksPage();else if(state.page==='tools'||state.page==='compose')content.innerHTML=toolsPage();else if(state.page==='settings')content.innerHTML=settingsPage();else if(state.page==='history')content.innerHTML=historyPage();else if(state.page==='titles')content.innerHTML=titlesPage();else if(state.page==='ratings')content.innerHTML=ratingsPage();else if(state.page==='trash')void trashPage();else content.innerHTML=collectionPage();content.insertAdjacentHTML('beforeend',footer());}
function worksPage(){const works=objs('work').filter(w=>state.page==='works'||w.data.type===state.page);const allStats=Object.values(state.stats);const total=allStats.reduce((n,s)=>n+s.words,0);const filtered=works.filter(matches).filter(w=>state.filter==='all'||(state.filter==='done'?w.data.status==='done':w.data.status!=='done')||w.data.folderId===state.filter);return `${head(btn('导入作品','import','','','upload')+btn('新建作品','new-work','primary','','plus'))}<section class="welcome"><div><h2>下一段精彩，等你写下。</h2><p>从一个想法，到一个世界。<br>让 AI 做你的创作伙伴，把故事的方向留在自己手中。</p>${btn('继续创作','open-work','primary',works[0]?.id??'','pen')}${btn('寻找灵感','nav','', 'ideas','spark')}</div><div class="welcome-art"><div class="paper back"></div><div class="paper"></div><span class="floating-spark">${icon('spark')}</span></div></section><section class="stats">${[['book',objs('work').length,'我的作品'],['pen',num(total),'累计正文字符'],['file',allStats.reduce((n,s)=>n+s.chapters,0),'创作章节'],['bulb',objs('idea').length,'灵感收藏']].map(([i,n,t])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><p>${t}</p></div></div>`).join('')}</section><div class="section-heading"><h2>作品书架 <span class="muted small">${works.length} 部作品</span></h2>${btn('管理文件夹','folders','small','','folder')}</div><div class="toolbar"><div class="tabs">${[['all','全部作品'],['writing','创作中'],['done','已完结']].map(([id,t])=>`<button class="tab ${state.filter===id?'active':''}" data-action="filter" data-id="${id}">${t}</button>`).join('')}</div>${search()}</div>${objs('folder').length?`<div class="chips">${objs('folder').map(f=>`<button class="chip ${state.filter===f.id?'active':''}" data-action="filter" data-id="${f.id}">${icon('folder')} ${esc(f.title)}</button>`).join('')}</div>`:''}<div class="grid" id="listing">${filtered.map(bookCard).join('')||empty('你的下一个故事，从这里开始','创建作品，或导入已有的 TXT / Markdown 文稿。','new-work','新建第一部作品')}</div>`}
function bookCard(w){const s=state.stats[w.id]??{words:0,chapters:0},p=Math.min(100,Math.round(s.words/(Number(w.data.target)||100000)*100));return `<article class="book-card"><button class="cover c${Number(w.data.color)||0}" data-action="open-work" data-id="${w.id}" aria-label="打开 ${esc(w.title)}"><small>INKFLOW ORIGINAL</small><strong>${esc(w.title)}</strong><small>${esc(w.data.genre??'原创作品')}</small></button><div class="book-info"><h3>${esc(w.title)}</h3><span class="tag">${typeLabels[w.data.type]??'小说'}</span> <span class="tag ${w.data.status==='done'?'green':'purple'}">${w.data.status==='done'?'已完结':'创作中'}</span>${w.data.demo?' <span class="tag">示例作品</span>':''}<p class="book-summary">${esc(w.data.summary||'故事还在等待第一笔，点击开始创作…')}</p><div class="book-count"><div><strong>${num(s.words)}</strong><span>已写</span></div><div><strong>${num(Number(w.data.target)||100000)}</strong><span>目标</span></div><div><strong>${s.chapters}</strong><span>章</span></div></div><div class="progress"><div style="width:${p}%"></div></div><div class="book-bottom"><span class="small">${date(w.updated)} · ${p}%</span><div class="actions">${ib('export',w.id,'download','导出作品')}${ib('edit',w.id,'settings','编辑作品信息')}${ib('delete',w.id,'trash','移至回收站')}${btn('开始写作','open-work','small primary',w.id,'pen')}</div></div></div></article>`}
const collectionKinds={templates:'prompt',agents:'agent',workflows:'workflow',analysis:'analysis',sources:'source',knowledge:'knowledge',ideas:'idea',skills:'skill'};
function collectionPage(){const kind=collectionKinds[state.page]??'knowledge';let rows=objs(kind).filter(matches);const categories=[...new Set(objs(kind).flatMap(r=>r.data.category?[r.data.category]:[]))];if(state.filter!=='all')rows=rows.filter(r=>r.data.category===state.filter||state.filter==='favorite'&&r.data.favorite);const ico={prompt:'file',agent:'bot',workflow:'flow',idea:'bulb',knowledge:'library',analysis:'library',source:'globe',skill:'check'}[kind];let extra='';if(kind==='prompt')extra=`<div class="chips"><button class="chip ${state.filter==='all'?'active':''}" data-action="filter" data-id="all">全部模板</button><button class="chip ${state.filter==='favorite'?'active':''}" data-action="filter" data-id="favorite">我的收藏</button>${categories.map(c=>`<button class="chip ${state.filter===c?'active':''}" data-action="filter" data-id="${esc(c)}">${esc(c)}</button>`).join('')}</div>`;const tips={analysis:'粘贴你有权使用的文本，结合“结构拆解”工具做分析。这里保存的是你自己的分析笔记。',sources:'此版本提供来源链接与阅读笔记管理，不会自动抓取网站或显示虚构的全网榜单。',agents:'智能体由系统提示词、写作技能和作品上下文组成。回复生成候选稿，不会直接修改正文。',workflows:'每条工作流最多 6 步，按顺序调用模型，前一步结果传递到下一步；每步结果可在生成记录中查看。'};return `${head((kind==='agent'?btn('管理写作技能','nav','','skills','library'):'')+btn('新增'+({prompt:'模板',agent:'智能体',workflow:'工作流',knowledge:'知识点',idea:'灵感',analysis:'分析笔记',source:'资料',skill:'技能'}[kind]),'new-object','primary',kind,'plus'))}${tips[kind]?`<div class="notice">${tips[kind]}</div>`:''}<div class="toolbar"><span class="muted small">共 ${objs(kind).length} 条${kind==='knowledge'?' · 支持标签、全文搜索和作品关联':''}</span>${search()}</div>${extra}<div class="cards" id="listing">${rows.map(o=>`<article class="card"><div class="card-top"><span class="tile-icon ${kind==='agent'||kind==='idea'?'purple':''}">${icon(ico)}</span><div><h3>${esc(o.title)}</h3><span class="muted tiny">${o.data.category?esc(o.data.category):date(o.updated)}</span></div></div><p class="preview">${esc(o.data.content||o.data.steps?.join(' → ')||o.data.url||'还没有内容')}</p><div class="actions">${(o.data.tags??[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><div class="actions">${ib('edit',o.id,'pen','编辑')}${ib('delete',o.id,'trash','移至回收站')}${kind==='prompt'?ib('favorite',o.id,o.data.favorite?'star':'heart',o.data.favorite?'取消收藏':'收藏'):''}</div>${['prompt','agent','workflow'].includes(kind)?btn(kind==='workflow'?'运行工作流':'开始使用','use','small primary',o.id,'spark'):btn('查看详情','detail','small',o.id,'arrow')}</div></article>`).join('')||empty('给灵感一个落脚的地方','点击右上角新增，保存你自己的创作资料。')}</div>`}
function toolsPage(){if(state.page==='compose')return composePage();return `${head()}<section class="welcome"><div><h2>你的 AI 创作工坊</h2><p>从故事结构到句子表达，选一个工具，开始打磨你的作品。<br>所有生成结果都由你决定是否采用。</p></div><div class="welcome-art"><div class="paper"></div><span class="floating-spark">${icon('spark')}</span></div></section><div class="cards">${objs('prompt').map((p,i)=>`<article class="card"><div class="card-top"><span class="tile-icon ${i%3===1?'purple':''}">${icon(['file','pen','spark','flow','library','bot'][i%6])}</span><div><h3>${esc(p.title)}</h3><span class="tag">${esc(p.data.category)}</span></div></div><p class="preview">${esc(p.data.content)}</p><div class="card-bottom"><span class="muted tiny">可关联作品与知识库</span>${btn('开始创作','use','small primary',p.id,'arrow')}</div></article>`).join('')}</div>`}
function options(kind,selected='',none='不关联'){return `<option value="">${none}</option>`+objs(kind).map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.title)}</option>`).join('')}
function field(label,html,hint=''){return `<label class="field">${label}${html}${hint?`<small>${hint}</small>`:''}</label>`}
function composePage(){const tool=object(state.tool);if(!tool)return empty('请选择创作工具','从创作工具、模板、智能体或工作流中选择一个。','nav','返回');const job=state.job?state.jobs.find(j=>j.id===state.job):null;return `<div class="page-head"><div><button class="muted small" data-action="nav" data-id="tools">${icon('back')} 返回创作工具</button><h1 style="margin-top:15px">${esc(tool.title)}</h1><p>${tool.kind==='workflow'?'按步骤执行，结果逐步传递':'给出你的要求，AI 将结合选定资料生成候选稿。'}</p></div>${btn('模型设置','nav','','settings','settings')}</div>${!state.keyConfigured?'<div class="notice warning">尚未配置模型密钥。你可以先编辑作品和素材；使用 AI 前，请在模型设置中完成配置。</div>':''}<div class="two-col"><section class="panel"><form id="generate-form" class="form-stack"><input type="hidden" name="toolId" value="${tool.id}">${field('关联作品',`<select name="workId">${options('work',state.work?.id,'不关联作品')}</select>`)}${field('你的创作要求',`<textarea name="instruction" rows="8" required maxlength="12000" placeholder="例如：为雾海来信设计一个中段转折。主角必须付出代价，反转需要前文线索支撑。"></textarea>`)}${field('引用知识点（可多选，最多 8 项）',`<select name="knowledgeIds" multiple size="4">${objs('knowledge').map(o=>`<option value="${o.id}">${esc(o.title)}</option>`).join('')}</select>`)}<div class="notice">${esc(tool.kind==='workflow'?tool.data.steps?.join('\n→ '):tool.data.content)}</div><button class="btn primary" type="submit">${icon('spark')} ${tool.kind==='workflow'?'运行工作流':'生成候选稿'}</button></form></section><section class="panel"><div class="section-heading"><h2>候选稿</h2><span class="tag">作者审核后使用</span></div><div id="compose-result">${job?jobResult(job):'<div class="result empty-result">让灵感开始流动。<br>生成结果会出现在这里。</div>'}</div></section></div>`}
function jobResult(j){return `<div class="notice ${j.state==='failed'?'warning':''}">${esc(statusLabel(j.state))} · ${esc(j.data.error??j.data.label)}${j.data.outputs?.length?` · 已完成 ${j.data.outputs.length}/${j.data.steps.length} 步`:''}</div>${j.state==='completed'?`<div class="result">${esc(j.data.result)}</div><div class="result-toolbar">${btn('复制正文','copy-job','small',j.id,'copy')}${btn('导出 TXT','export-job','small',j.id,'download')}${j.data.chapterId&&!j.data.applied?btn('追加到章节','apply-job','small primary',j.id,'check'):''}${j.data.chapterId&&!j.data.applied?btn('替换章节','replace-job','small danger',j.id):''}${btn('存为知识点','job-knowledge','small',j.id,'library')}</div>`:j.state==='running'||j.state==='queued'?`<div class="result empty-result">${icon('spark')}模型正在创作，请稍候。<br>可以离开当前页面，稍后在生成记录中查看。</div><div class="result-toolbar">${btn('取消任务','cancel-job','small danger',j.id)}</div>`:''}${(j.data.outputs?.length??0)>1?j.data.outputs.map(o=>`<details class="version-item"><summary class="small">第 ${o.step} 步输出 · ${esc(o.model)}</summary><div class="detail-text">${esc(o.text)}</div></details>`).join(''):''}`}
function statusLabel(s){return {queued:'等待开始',running:'生成中',completed:'已完成',failed:'生成失败',cancelled:'已取消',interrupted:'服务重启，任务已中断'}[s]??s}
function historyPage(){return `${head(btn('刷新记录','refresh','','','clock'))}<div class="panel">${state.jobs.length?state.jobs.map(j=>`<div class="job"><div><h3>${esc(j.data.label)}</h3><p>${date(j.created)} · ${esc(j.data.instruction.slice(0,65))}</p></div><div class="actions"><span class="job-status ${j.state}">${statusLabel(j.state)}</span>${btn('查看','view-job','small',j.id,'arrow')}${['running','queued'].includes(j.state)?btn('取消','cancel-job','small danger',j.id):''}</div></div>`).join(''):empty('还没有生成记录','使用创作工具、智能体或工作流后，任务会记录在这里。')}</div>`}
function settingsPage(){const c=state.config;return `${head()}<div class="two-col"><section class="panel"><h2>模型连接</h2><div class="notice ${state.keyConfigured?'':'warning'}">${state.keyConfigured?'服务端已读取密钥，前端无法查看密钥。':'尚未检测到 WRITING_API_KEY，请按右侧说明配置并重启。'}</div><form id="settings-form" class="form-stack">${field('接口根地址',`<input name="baseUrl" value="${esc(c.baseUrl)}" placeholder="https://api.openai.com/v1" required>`,'填写到 /v1 为止，不要附加 /chat/completions。')}${field('模型名称',`<input name="model" value="${esc(c.model)}" placeholder="填写你的服务商提供的模型 ID" required maxlength="120">`)}<div class="form-row">${field('创意温度（0–2）',`<input name="temperature" type="number" min="0" max="2" step="0.1" value="${c.temperature}">`)}${field('最大输出 Token',`<input name="maxTokens" type="number" min="128" max="16000" value="${c.maxTokens}">`)}</div><button class="btn primary" type="submit">${icon('save')} 保存模型配置</button></form></section><section class="panel"><h2>本地配置指引</h2><ol class="settings-list"><li>在项目目录将 .env.example 复制为 .env。</li><li>填入服务商的 API Key，并将接口域名加入允许列表。</li><li>关闭启动窗口，重新运行 start.cmd。</li><li>在左侧填写接口和模型名称，保存。</li><li>打开一个创作工具，用简短要求验证连接。</li></ol><div class="code">WRITING_API_KEY=你的密钥\nWRITING_ALLOWED_HOSTS=${esc(state.allowedHosts.join(','))}</div><p class="small muted" style="line-height:1.9;margin-top:16px">仅支持公网 HTTPS 的兼容 Chat Completions 接口；不跟随重定向。生成请求会把你选择的作品、当前章节与知识点发送到该服务商。没有选择的其他作品不会作为上下文发送。</p></section></div><div class="panel"><h2>备份与迁移</h2><p class="small muted">数据库位于项目 data 文件夹。JSON 备份包含作品、章节、历史版本及素材，不包含密钥、模型配置或生成记录。恢复会整体替换现有作品与素材，请先导出当前备份。</p><div class="actions">${btn('导出完整文稿备份','backup','','','download')}${btn('从备份恢复','restore-backup','danger','','upload')}</div></div><div class="notice warning">此版本面向单人本机使用，只监听 127.0.0.1。没有实现多用户账号、支付订阅、公开分享或企业权限，请勿直接暴露到公网。</div>`}
function titlesPage(){return `${head()}<div class="two-col"><section class="panel"><h2>书名表达检查</h2><p class="small muted">本地规则检查，不调用模型，不代表市场热度或商业成绩预测。</p><form id="title-form" class="form-stack">${field('想测试的书名','<input name="title" required maxlength="180" placeholder="例如：雾海来信">')}${field('题材与读者定位','<input name="genre" maxlength="100" placeholder="例如：悬疑幻想 / 喜欢谜题的读者">')}<button class="btn primary" type="submit">${icon('flask')} 开始检查</button></form></section><section class="panel" id="title-result"><div class="result empty-result">检查长度、辨识度和冲突表达。<br>结果用于修改参考，不是点击率预测。</div></section></div>`}
function ratingsPage(){const rows=objs('rating').filter(matches);const grouped={};for(const r of rows){const model=r.data.model||'未命名模型';(grouped[model]??=[]).push(Number(r.data.score)||0)}return `${head(btn('新增评测','new-object','primary','rating','plus'))}<div class="notice">这里是你的个人实测记录，不是全网模型排行榜。评分由你填写；没有评测数据时，不生成虚构排名。</div><div class="panel"><h2>我的模型对比</h2>${Object.keys(grouped).length?`<table class="table"><thead><tr><th>模型</th><th>评测次数</th><th>平均分 / 10</th></tr></thead><tbody>${Object.entries(grouped).sort((a,b)=>b[1].reduce((n,v)=>n+v,0)/b[1].length-a[1].reduce((n,v)=>n+v,0)/a[1].length).map(([name,scores])=>`<tr><td>${esc(name)}</td><td>${scores.length}</td><td>${(scores.reduce((n,v)=>n+v,0)/scores.length).toFixed(1)}</td></tr>`).join('')}</tbody></table>`:empty('先记录一次实际体验','对相同写作任务，比较模型的语言、结构和一致性。')}</div><div class="toolbar"><h2>评测笔记</h2>${search()}</div><div class="cards">${rows.map(r=>`<article class="card"><h3>${esc(r.title)}</h3><p>${esc(r.data.model)} · ${esc(r.data.score)} / 10</p><p class="preview">${esc(r.data.content)}</p><div class="card-bottom">${btn('编辑','edit','small',r.id)}${btn('删除','delete','small danger',r.id)}</div></article>`).join('')}</div>`}
async function trashPage(){try{const rows=await api('trash');$('#content').innerHTML=`${head()}<div class="notice">删除作品会隐藏其章节，但不会清空正文和历史版本。恢复后可以继续编辑。</div><div class="panel">${rows.length?rows.map(r=>`<div class="job"><div><h3>${esc(r.title)}</h3><p>${esc(r.kind)} · ${date(r.updated)}</p></div>${btn('恢复','restore-object','small primary',r.id,'back')}</div>`).join(''):empty('回收站是空的','移除的作品与素材会出现在这里。')}</div>${footer()}`}catch(e){toast(e.message)}}
function modal(title,body,actions=''){const d=$('#modal');d.innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close()}
function objectForm(kind,id){const o=id?object(id):null,d=o?.data??{},isWork=kind==='work';let fields=field(isWork?'作品名称':'标题',`<input name="title" value="${esc(o?.title)}" maxlength="180" required placeholder="给你的${isWork?'故事':'资料'}起个名字">`);if(isWork){fields+=`<div class="form-row">${field('作品类型',`<select name="type">${Object.entries(typeLabels).map(([v,t])=>`<option value="${v}" ${(d.type??(state.page==='short'?'short':state.page==='script'?'script':'novel'))===v?'selected':''}>${t}</option>`).join('')}</select>`)}${field('题材',`<input name="genre" value="${esc(d.genre)}" maxlength="100" placeholder="悬疑 / 现实 / 奇幻…">`)}</div>${field('一句话简介',`<textarea name="summary" rows="3" maxlength="2000">${esc(d.summary)}</textarea>`)}<div class="form-row">${field('目标字符数',`<input name="target" type="number" min="1" max="100000000" value="${d.target??100000}" required>`)}${field('创作状态',`<select name="status"><option value="writing">创作中</option><option value="done" ${d.status==='done'?'selected':''}>已完结</option></select>`)}</div><div class="form-row">${field('封面配色',`<select name="color">${['雾海蓝','暮光紫','森林绿','暖沙棕'].map((t,i)=>`<option value="${i}" ${Number(d.color)===i?'selected':''}>${t}</option>`).join('')}</select>`)}${field('作品文件夹',`<select name="folderId">${options('folder',d.folderId,'未分类')}</select>`)}</div>`;}else{
      if(['character','world','outline','knowledge','analysis','idea'].includes(kind))fields+=field('关联作品',`<select name="workId">${options('work',d.workId??state.work?.id)}</select>`);
      if(kind==='source')fields+=field('资料来源 URL',`<input name="url" type="url" maxlength="2000" placeholder="https://…" value="${esc(d.url)}">`,'只记录来源地址，不会自动抓取。');
      if(kind==='prompt')fields+=field('分类',`<input name="category" maxlength="60" value="${esc(d.category??'自定义')}">`);
      if(kind==='rating')fields+=`<div class="form-row">${field('模型名称',`<input name="model" required value="${esc(d.model??state.config.model)}" maxlength="120">`)}${field('个人评分 / 10',`<input name="score" type="number" min="0" max="10" step="0.5" required value="${d.score??8}">`)}</div>`;
      fields+=field(kind==='agent'?'系统提示词':kind==='workflow'?'用途说明':'正文 / 笔记',`<textarea name="content" rows="7" maxlength="18000" ${kind!=='folder'?'required':''} placeholder="写下你的内容…">${esc(d.content)}</textarea>`);
      if(kind==='workflow')fields+=field('执行步骤（每行一步，最多 6 步）',`<textarea name="steps" rows="6" required maxlength="24000" placeholder="根据创意生成故事设定\n基于设定生成大纲\n根据大纲创作开篇">${esc(d.steps?.join('\n'))}</textarea>`);
      if(kind==='agent')fields+=field('引用写作技能（可多选）',`<select name="skills" multiple size="3">${objs('skill').map(s=>`<option value="${s.id}" ${d.skills?.includes(s.id)?'selected':''}>${esc(s.title)}</option>`).join('')}</select>`);
      if(kind!=='folder')fields+=field('标签（用逗号分隔）',`<input name="tags" value="${esc(d.tags?.join(', '))}" maxlength="300" placeholder="情节, 人物, 待整理">`);
    }modal(o?'编辑'+(isWork?'作品':'资料'):isWork?'新建作品':'新增资料',`<form id="object-form" class="form-stack" data-kind="${kind}" data-id="${o?.id??''}">${fields}<div class="modal-actions">${btn('取消','close-modal')}<button class="btn primary" type="submit">${icon('check')} 保存${isWork?'作品':'资料'}</button></div></form>`);}
async function openWork(id){if(!id){objectForm('work');return}if(!(await saveEditor()))return;state.work=object(id);state.chapters=await api('chapters?work='+id);state.chapter=state.chapters.length?await api('chapters/'+state.chapters[0].id):null;state.dirty=false;state.page='editor';layout();}
function renderEditor(){const w=state.work,c=state.chapter;if(!w){state.page='works';renderPage();return}$('#content').innerHTML=`<div class="page-head editor-head"><div><button data-action="nav" data-id="works" class="muted small">${icon('back')} 返回书架</button><h1 style="margin-top:13px">${esc(w.title)}</h1><p>${typeLabels[w.data.type]} · ${esc(w.data.genre)} · ${state.chapters.length} 章</p></div><div class="actions">${btn('人物 / 设定','work-notes','','','library')}${btn('导出作品','export','',w.id,'download')}${btn('保存章节','save-editor','primary','','save')}</div></div><div class="editor-layout"><aside class="chapter-nav"><div class="chapter-heading"><span>章节目录</span>${ib('new-chapter',w.id,'plus','新增章节')}</div>${state.chapters.map(ch=>`<button class="chapter-item ${c?.id===ch.id?'active':''}" data-action="open-chapter" data-id="${ch.id}">${esc(ch.title)}<small>${num(ch.words)} 字符</small></button>`).join('')||'<p class="muted small">点击 + 新建第一章</p>'}</aside><section class="manuscript">${c?`<input class="editor-title" id="chapter-title" aria-label="章节标题" maxlength="180" value="${esc(c.title)}"><textarea class="editor-body" id="chapter-content" aria-label="章节正文" placeholder="故事从这里开始…" maxlength="250000">${esc(c.content)}</textarea><div class="editor-foot"><span id="save-state" class="save-state">已保存 · 版本 ${c.revision}</span><span><b id="word-count">${count(c.content)}</b> 字符 · ${btn('历史版本','versions','small',c.id,'clock')}</span></div>`:empty('写下第一章','章节内容会自动保存到本地数据库。','new-chapter','新建章节')}</section><aside class="ai-panel"><h3>${icon('spark')} AI 创作助手</h3><form id="editor-generate" class="form-stack">${field('创作模板',`<select name="promptId">${objs('prompt').map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select>`)}${field('补充要求','<textarea name="instruction" rows="5" required maxlength="12000" placeholder="例如：继续写林序打开信封后的行动。保持克制的悬疑氛围。"></textarea>')}<p class="muted tiny">会发送当前章节及本作品人物、世界观、细纲；不会发送其他作品。</p><button class="btn primary" type="submit" ${!c?'disabled':''}>${icon('spark')} 生成候选稿</button></form><div id="editor-result" style="margin-top:20px">${state.job&&state.jobs.find(j=>j.id===state.job)?jobResult(state.jobs.find(j=>j.id===state.job)):'<p class="muted tiny" style="line-height:1.9">候选稿不会自动写入章节。生成期间若正文发生修改，将阻止自动覆盖。</p>'}</div></aside></div>`;}
async function saveEditor(){clearTimeout(state.editorTimer);if(state.saving){const ok=await state.saving;if(!ok)return false;if(state.dirty)return saveEditor();return true}if(!state.dirty||!state.chapter)return true;const c=state.chapter,title=$('#chapter-title')?.value,content=$('#chapter-content')?.value;if(content===undefined)return false;const indicator=$('#save-state');if(indicator)indicator.textContent='保存中…';state.saving=(async()=>{try{const saved=await api('chapters/'+c.id,'PUT',{title,content,revision:c.revision});state.chapter=saved;state.dirty=$('#chapter-content')?.value!==content||$('#chapter-title')?.value!==title;if(indicator){indicator.textContent=`已保存 · 版本 ${saved.revision}`;indicator.classList.remove('error')}return true}catch(e){if(indicator){indicator.textContent=e.message;indicator.classList.add('error')}toast(e.message);return false}})();const result=await state.saving;state.saving=null;if(result&&state.dirty)return saveEditor();return result}
async function navigate(page){if(!(await saveEditor()))return;await refresh();state.page=page;state.filter='all';state.search='';layout();window.scrollTo(0,0)}
async function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function chooseFile(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',()=>resolve(input.files?.[0]));input.addEventListener('cancel',()=>resolve(null));input.click()})}
async function generate(form,editor=false){if(editor&&!(await saveEditor()))return;const f=new FormData(form),tool=object(f.get('toolId'));const input={instruction:f.get('instruction'),knowledgeIds:f.getAll('knowledgeIds')};if(editor)Object.assign(input,{workId:state.work.id,chapterId:state.chapter.id,promptId:f.get('promptId'),label:object(f.get('promptId'))?.title});else Object.assign(input,{workId:f.get('workId')||null,[tool.kind==='agent'?'agentId':tool.kind==='workflow'?'workflowId':'promptId']:tool.id,label:tool.title});const button=form.querySelector('[type="submit"]');button.disabled=true;try{const job=await api('jobs','POST',input);state.jobs.unshift(job);state.job=job.id;const target=$(editor?'#editor-result':'#compose-result');if(target)target.innerHTML=jobResult(job);toast('生成任务已创建')}finally{button.disabled=false}}
document.addEventListener('input',event=>{if(event.target.matches('#chapter-content,#chapter-title')){state.dirty=true;$('#save-state').textContent='正在编辑…';$('#word-count').textContent=count($('#chapter-content').value);clearTimeout(state.editorTimer);state.editorTimer=setTimeout(()=>void saveEditor(),1100);}if(event.target.id==='search'){state.search=event.target.value;const pos=event.target.selectionStart;renderPage();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);}});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();void saveEditor().then(ok=>ok&&toast('已保存'))}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{
  if(form.id==='object-form'){
    const f=new FormData(form),old=object(form.dataset.id),kind=form.dataset.kind,data={...old?.data};
    for(const [k,v] of f)if(k!=='title')data[k]=v;
    if(f.has('tags'))data.tags=String(f.get('tags')).split(/[,，]/).map(s=>s.trim()).filter(Boolean).slice(0,20);
    if(kind==='work'){data.target=Number(f.get('target'));data.color=Number(f.get('color'));if(!Number.isFinite(data.target)||data.target<1)throw new Error('目标字符数不正确');}
    if(kind==='agent')data.skills=f.getAll('skills');
    if(kind==='workflow'){data.steps=String(f.get('steps')).split('\n').map(s=>s.trim()).filter(Boolean);if(data.steps.length<1||data.steps.length>6)throw new Error('工作流需要 1–6 个步骤');}
    if(kind==='rating'){data.score=Number(f.get('score'));if(data.score<0||data.score>10)throw new Error('评分范围 0–10');}
    await api('objects'+(old?'/'+old.id:''),old?'PUT':'POST',{kind,title:f.get('title'),data,revision:old?.revision});closeModal();await refresh();renderPage();toast('已保存');
  }else if(form.id==='settings-form'){const f=new FormData(form);await api('config','PUT',{baseUrl:f.get('baseUrl'),model:f.get('model'),temperature:Number(f.get('temperature')),maxTokens:Number(f.get('maxTokens'))});await refresh();renderPage();toast('模型配置已保存');}
  else if(form.id==='generate-form')await generate(form);
  else if(form.id==='editor-generate')await generate(form,true);
  else if(form.id==='chapter-form'){if(!(await saveEditor()))return;const f=new FormData(form);const ch=await api('chapters','POST',{work_id:state.work.id,title:f.get('title'),content:''});closeModal();state.chapters=await api('chapters?work='+state.work.id);state.chapter=ch;renderEditor();}
  else if(form.id==='import-form'){const f=new FormData(form);const text=await state.importFile.text();await api('import','POST',{title:f.get('title'),type:f.get('type'),text});closeModal();await refresh();renderPage();toast('导入成功，按章节标题完成拆分');}
  else if(form.id==='title-form'){const f=new FormData(form),title=String(f.get('title')).trim(),n=count(title);const checks=[[n>=3&&n<=18,'长度 3–18 字符便于展示',n<3?'标题过短，可以增加独特信息。':n>18?'标题较长，试着压缩核心冲突。':'长度适合大多数展示位置。'],[!/[!！?？]{2,}/.test(title),'标点保持克制','避免用连续感叹号代替故事吸引力。'],[!/(最强|无敌|震惊|绝世|逆天)/.test(title),'减少泛化的夸张词','同类词较常见，可以换成更具体的人物、物件或困境。'],[/[海雾信城夜人门钟日月火雪风梦归失来]/.test(title),'包含具体意象或行动','意象可以帮助形成画面，但不能代替题材与故事定位。']];const score=Math.round(checks.filter(c=>c[0]).length/4*100);$('#title-result').innerHTML=`<h2>${esc(title)}</h2><p class="muted small">${esc(f.get('genre')||'未填写读者定位')}</p><div class="title-score">${score}<span> / 100 · 规则检查分</span></div>${checks.map(([ok,label,note])=>`<div class="notice ${ok?'':'warning'}">${ok?'✓':'○'} ${label}<br><span class="tiny">${note}</span></div>`).join('')}<p class="muted tiny">仅为四项规则各占 25 分的检查，不是 AI 评估、版权查重、热度或收益预测。</p>`;}
}catch(e){toast(e.message)}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;try{
  if(action==='nav')await navigate(id);
  else if(action==='menu')$('.sidebar').classList.toggle('open');
  else if(action==='theme'){document.documentElement.classList.toggle('theme-dark');localStorage.setItem('inkflow-theme',document.documentElement.classList.contains('theme-dark')?'dark':'light');}
  else if(action==='new-work')objectForm('work');
  else if(action==='new-object')objectForm(id);
  else if(action==='edit')objectForm(object(id).kind,id);
  else if(action==='close-modal')closeModal();
  else if(action==='filter'){state.filter=id;renderPage()}
  else if(action==='open-work')await openWork(id);
  else if(action==='save-editor'){if(await saveEditor())toast('章节已保存');}
  else if(action==='open-chapter'){if(!(await saveEditor()))return;state.chapter=await api('chapters/'+id);renderEditor();}
  else if(action==='new-chapter')modal('新建章节',`<form id="chapter-form" class="form-stack">${field('章节名称',`<input name="title" required maxlength="180" value="第 ${state.chapters.length+1} 章">`)}<button type="submit" class="btn primary">创建章节</button></form>`);
  else if(action==='delete'){if(confirm(`将“${object(id).title}”移至回收站？可以恢复。`)){await api('objects/'+id,'DELETE');await refresh();renderPage();toast('已移至回收站');}}
  else if(action==='restore-object'){await api('objects/'+id+'/restore','POST');await refresh();renderPage();toast('已恢复');}
  else if(action==='favorite'){const o=object(id);await api('objects/'+id,'PUT',{...o,data:{...o.data,favorite:!o.data.favorite}});await refresh();renderPage();}
  else if(action==='detail'){const o=object(id);modal(o.title,`${o.data.url?`<p><a href="${esc(/^https?:\/\//.test(o.data.url)?o.data.url:'#')}" target="_blank" rel="noopener noreferrer">${esc(o.data.url)}</a></p>`:''}<div class="detail-text">${esc(o.data.content)}</div>`);}
  else if(action==='use'){if(!(await saveEditor()))return;state.tool=id;state.page='compose';state.job=null;layout();}
  else if(action==='refresh'){await refresh();renderPage();}
  else if(action==='view-job'){const j=state.jobs.find(j=>j.id===id);modal(j.data.label,jobResult(j));}
  else if(action==='copy-job'){await navigator.clipboard.writeText(state.jobs.find(j=>j.id===id).data.result);toast('已复制候选稿');}
  else if(action==='export-job'){const j=state.jobs.find(j=>j.id===id);await download(j.data.label+'.txt',j.data.result);}
  else if(action==='job-knowledge'){const j=state.jobs.find(j=>j.id===id);await api('objects','POST',{kind:'knowledge',title:j.data.label+' · '+date(j.created),data:{content:j.data.result,tags:['AI 候选稿']}});await refresh();toast('已存入知识库');}
  else if(action==='cancel-job'){await api('jobs/'+id+'/cancel','POST');await refresh();const target=$('#compose-result')??$('#editor-result');if(target)target.innerHTML=jobResult(state.jobs.find(j=>j.id===id));toast('已请求取消');}
  else if(action==='apply-job'||action==='replace-job'){if(!(await saveEditor()))return;if(action==='replace-job'&&!confirm('用候选稿替换当前整章？原文会保存在章节历史版本中。'))return;const ch=await api('jobs/'+id+'/apply','POST',{mode:action==='replace-job'?'replace':'append'});await refresh();if(state.chapter?.id===ch.id){state.chapter=ch;state.dirty=false;renderEditor()}closeModal();toast('已应用候选稿，原稿已留存历史版本');}
  else if(action==='export'){if(!(await saveEditor()))return;const w=object(id),chapters=await api('chapters?work='+id),full=await Promise.all(chapters.map(c=>api('chapters/'+c.id)));await download(w.title+'.txt',w.title+'\n\n'+full.map(c=>c.title+'\n\n'+c.content).join('\n\n'));}
  else if(action==='backup'){if(!(await saveEditor()))return;const backup=await api('backup');await download('墨舟文稿备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(backup,null,2),'application/json');toast('备份已导出，不包含 API 密钥');}
  else if(action==='restore-backup'){const file=await chooseFile('.json');if(!file)return;if(file.size>30000000)throw new Error('备份超过 30 MB');if(!confirm('恢复会替换当前全部作品、章节和素材。确认已导出当前备份？'))return;const confirmText=prompt('请输入：恢复备份');if(confirmText!=='恢复备份')return;await api('backup','POST',{snapshot:JSON.parse(await file.text()),confirm:confirmText});await refresh();renderPage();toast('备份已恢复');}
  else if(action==='import'){const file=await chooseFile('.txt,.md');if(!file)return;if(file.size>5000000)throw new Error('单文件不能超过 5 MB，请拆分导入。');state.importFile=file;modal('导入作品',`<form id="import-form" class="form-stack"><div class="notice">${esc(file.name)} · ${(file.size/1024).toFixed(1)} KB<br>请使用 UTF-8 编码，按“第 X 章”标题自动分章；单章最多 25 万字符。</div>${field('作品名称',`<input name="title" value="${esc(file.name.replace(/\.(txt|md)$/i,''))}" maxlength="180" required>`)}${field('作品类型',`<select name="type">${Object.entries(typeLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`)}<button type="submit" class="btn primary">确认导入</button></form>`);}
  else if(action==='folders'){modal('作品文件夹',`<div class="form-stack">${objs('folder').map(f=>`<div class="job"><span>${esc(f.title)}</span><span class="actions">${ib('edit',f.id,'pen','编辑文件夹')}${ib('delete',f.id,'trash','删除文件夹')}</span></div>`).join('')||'<p class="muted small">还没有文件夹。在作品设置中可以选择归属。</p>'}${btn('新增文件夹','new-object','primary','folder','plus')}</div>`);}
  else if(action==='work-notes'){modal('人物、世界观与细纲',`<div class="chips">${[['character','新增人物'],['world','新增世界观'],['outline','新增细纲']].map(([k,t])=>btn(t,'new-object','small',k,'plus')).join('')}</div>${state.objects.filter(o=>['character','world','outline'].includes(o.kind)&&o.data.workId===state.work.id).map(o=>`<div class="version-item"><h3>${esc(o.title)}</h3><p>${esc(o.data.content)}</p><div class="actions">${btn('编辑','edit','small',o.id)}${btn('删除','delete','small danger',o.id)}</div></div>`).join('')||'<p class="muted small">作品设定将作为 AI 的上下文。</p>'}`);}
  else if(action==='versions'){if(!(await saveEditor()))return;const rows=await api('chapters/'+id+'/versions');modal('章节历史版本',rows.length?rows.map(v=>`<div class="version-item"><h3>版本 ${v.revision} · ${esc(v.title)}</h3><p>${date(v.created)} · ${count(v.content)} 字符</p><p>${esc(v.content.slice(0,400))}</p>${btn('恢复此版本','restore-version','small',v.id,'back')}</div>`).join(''):'<p class="muted small">本章首次修改后会保存历史版本，保留最近 80 次。</p>');state.versions=rows;}
  else if(action==='restore-version'){const v=state.versions.find(v=>v.id===id);if(!confirm('恢复历史版本？当前正文也会保存为历史版本。'))return;state.chapter=await api('chapters/'+state.chapter.id,'PUT',{title:v.title,content:v.content,revision:state.chapter.revision});state.dirty=false;closeModal();renderEditor();toast('已恢复历史版本');}
  else if(action==='help')modal('墨舟使用指南','<div class="detail-text">1. 新建作品：设置类型、题材、简介和目标字符数。\n2. 开始写作：添加章节，正文修改后约一秒自动保存；Ctrl+S 可立即保存。\n3. 人物与设定：在编辑器右上方管理本作品的人物、世界观和细纲。\n4. AI 创作：先在模型设置配置接口，并在本地 .env 填入密钥；选择工具或智能体后提交要求。\n5. 审核候选稿：复制、导出或追加到章节。正文如有新修改，系统会阻止自动覆盖。\n6. 工作流：每行一个步骤，最多六步。可随时在生成记录查看或取消。\n7. 备份：模型与数据页面可导出全部文稿；单部作品可导出 TXT。\n8. 本地数据在 data/inkflow.sqlite；关闭窗口会停止服务，不会删除数据。\n\n本机单人版，不含收费、公开社区和自动爬虫；书名规则分不代表市场成绩。完整部署说明见项目 README.md。</div>');
}catch(e){toast(e.message)}});
async function poll(){try{if(!state.initialized)return;const active=state.jobs.filter(j=>['running','queued'].includes(j.state));if(!active.length)return;const updated=await Promise.all(active.map(j=>api('jobs/'+j.id)));for(const j of updated){const old=state.jobs.findIndex(v=>v.id===j.id);state.jobs[old]=j;if(j.state==='completed')toast(j.data.label+'已生成，可查看候选稿');}const j=state.jobs.find(j=>j.id===state.job);if(j){const t=$('#compose-result')??$('#editor-result');if(t)t.innerHTML=jobResult(j)}if(state.page==='history'&&!$('#modal').open)renderPage();if($('#modal').open){const viewed=updated.find(j=>$('#modal .modal-heading h2')?.textContent===j.data.label);if(viewed)modal(viewed.data.label,jobResult(viewed));}}catch{}}
if(localStorage.getItem('inkflow-theme')==='dark')document.documentElement.classList.add('theme-dark');
try{await refresh();state.initialized=true;layout();setInterval(poll,2200)}catch(e){$('#app').innerHTML=`<div class="loading"><div><h2>暂时无法打开创作空间</h2><p>${esc(e.message)}</p><p>请确认 start.cmd 窗口仍在运行，然后刷新页面。</p></div></div>`;}
